window.kbPageData["views/entry/k-6092f66988e1dac5"] = {"key":"entry/k-6092f66988e1dac5","state":{"route":"entry/k-6092f66988e1dac5"},"node":{"id":"k-6092f66988e1dac5","mode":"k","title":"人数占比的分母整除总人数","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["人数占比为最简分数时，总人数须为分母的倍数"],"qs":["江苏 2024 C类 行测#57"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"当某类人数占总人数的比例恰为最简分数时，分母必须整除总人数。有多个这样的比例时，总人数是各分母最小公倍数的整数倍。","review":{"definition":"当某类人数占总人数的比例恰为最简分数时，分母必须整除总人数。有多个这样的比例时，总人数是各分母最小公倍数的整数倍。","explanation":"人数为整数。把比例约成最简分数后，分子和分母互质，分母只能从总人数中约去。两份公开题本均载明，50岁及以上居民占1/12，女性占7/16。12和16的最小公倍数是48，90至110之间只有96符合条件。50岁及以上有8人，30岁以下有（96－20）÷2＝38人，相差30人，选A。","references":[{"source":"web-92745d26e83e0238","location":"第57题题干","quote":"50岁及以上居民占1/12，女性占7/16"},{"source":"web-61daf72985c8ee40","location":"来源标注为2024江苏C-057的题干","quote":"50岁及以上居民占1/12，女性占7/16"}],"evidence":"居住总人数应既是12的整数倍又是16的整数倍","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 C类 行测#57":{"paper":"江苏 2024 C类 行测","n":57,"mod":"数量关系","src":["3f1ec77ae8a18519b57e.pdf",10],"asrc":["02d6b49839583bdaf297.pdf",16],"card":"f190d9142902f58b72e2f122","links":[{"id":"k-6092f66988e1dac5","role":"解题依据","why":"两类居民的人数均为整数，因此各最简分数的分母都须整除总人数。"}]}},"terms":{},"references":{"web-92745d26e83e0238":{"name":"爱真题《2024江苏省考行测真题及答案解析（C类）》","url":"https://m.aipta.com/article/9722.html"},"web-61daf72985c8ee40":{"name":"星光公考《2024年江苏公务员录用考试行测C卷》题库","url":"https://www.xingguanggongkao.com/Pc/XingQuestion/search/subject_id/2/keywords/R7XFIR-07DMA-XGVDI/p/59.html"}},"topics":[],"units":{"k-6092f66988e1dac5":[["江苏 2024 C类 行测#57"]]}};
